// Signed, expiring download token management.

import { createHmac, randomUUID } from "crypto";
import { getDb } from "../core/db.js";
import { orders } from "../core/schema.js";
import { eq } from "drizzle-orm";

const TOKEN_TTL_MS = 72 * 60 * 60 * 1000; // 72 hours
const SECRET = process.env["DOWNLOAD_TOKEN_SECRET"] ?? "dev-secret-change-in-prod";

export function generateDownloadToken(orderId: string): {
  token: string;
  expiresAt: Date;
} {
  const token = randomUUID();
  const expiresAt = new Date(Date.now() + TOKEN_TTL_MS);
  return { token, expiresAt };
}

export function signToken(token: string, expiresAt: Date): string {
  const payload = `${token}:${expiresAt.getTime()}`;
  const sig = createHmac("sha256", SECRET).update(payload).digest("hex").slice(0, 16);
  return `${payload}:${sig}`;
}

export function verifyToken(signed: string): boolean {
  const parts = signed.split(":");
  if (parts.length !== 3) return false;
  const [token, exp, sig] = parts;
  if (!token || !exp || !sig) return false;
  const expiresAt = parseInt(exp);
  if (Date.now() > expiresAt) return false;

  const payload = `${token}:${exp}`;
  const expected = createHmac("sha256", SECRET)
    .update(payload)
    .digest("hex")
    .slice(0, 16);

  return sig === expected;
}

export function getOrderByToken(token: string): typeof orders.$inferSelect | null {
  const db = getDb();
  return (
    db.select().from(orders).where(eq(orders.downloadToken, token)).get() ??
    null
  );
}

